@namespace sv_964cf20e5982420cb1bd06a52f06f1e0.Components.JobApplication
@using sv_964cf20e5982420cb1bd06a52f06f1e0.Models

<section class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h3>Application Submitted!</h3>
            <p>Your application has been submitted successfully. Your application ID is <strong>@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in References)
            {
                <div class="review-reference">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    <span class="text-muted">@reference.Email | @reference.Phone</span>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        <div class="step-actions">
            <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoStep.PersonalInfoResult Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceForm.ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnSubmitted { get; set; }

    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(Personal.FullName, Personal.Email, Personal.Phone, Personal.Address),
                new WorkHistory(WorkEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                CoverLetter
            );

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
            await OnSubmitted.InvokeAsync(ApplicationId);
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

