@page "/apply"
@using sv_964cf20e5982420cb1bd06a52f06f1e0.Components.JobApplication
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="job-application">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedUpTo="@completedUpTo"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@personalResult!"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmitted="HandleSubmitted" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private int completedUpTo = 0;

    // Personal info state
    private string personalFullName = string.Empty;
    private string personalEmail = string.Empty;
    private string personalPhone = string.Empty;
    private string personalAddress = string.Empty;
    private PersonalInfoStep.PersonalInfoResult? personalResult;

    // Work history state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { new() };

    // References state
    private List<ReferenceForm.ReferenceModel> references = new() { new(), new() };

    // Cover letter state
    private string coverLetter = string.Empty;

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalResult = result;
        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        AdvanceTo(1);
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        AdvanceTo(2);
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        AdvanceTo(3);
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        AdvanceTo(4);
    }

    private void HandleSubmitted(int applicationId)
    {
        // Application submitted — the ReviewStep handles the confirmation display
    }

    private void AdvanceTo(int step)
    {
        currentStep = step;
        if (step > completedUpTo)
        {
            completedUpTo = step;
        }
    }

    private void GoToStep(int step)
    {
        if (step < completedUpTo || step == currentStep)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }
}

.job-application {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
