arguments.new_str:
@namespace sv_964cf20e5982420cb1bd06a52f06f1e0.Components.JobApplication

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="OnStartDateChanged" />
        </div>

        <div class="form-group">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="OnCurrentChanged" />
                Currently working here
            </label>
        </div>

        @if (!IsCurrent)
        {
            <div class="form-group">
                <label>End Date</label>
                <input type="date" class="form-control" value="@EndDateValue"
                       @onchange="OnEndDateChanged" />
            </div>
        }
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" @onchange="OnDescriptionChanged">@Entry.Description</textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;
    private string EndDateValue => Entry.EndDate?.ToString("yyyy-MM-dd") ?? "";

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Company = (string?)e.Value ?? string.Empty });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Title = (string?)e.Value ?? string.Empty });

    private Task OnStartDateChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : DateTime.Today });

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        DateTime? endDate = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
        return OnChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        return OnChanged.InvokeAsync(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Description = (string?)e.Value ?? string.Empty });

    public record WorkEntryModel
    {
        public string Company { get; init; } = string.Empty;
        public string Title { get; init; } = string.Empty;
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = string.Empty;
    }
}

